package dev.cosmerearcanists.nicrosil;

import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class NicrosilLedgerTest {
    @Test void copiedReferencesShareAConsumablePowerRatherThanDuplicatingIt(){var ledger=new NicrosilLedger();var mind=new NicrosilLedger.Mind(UUID.randomUUID(),null,600);assertTrue(ledger.add(mind,10));var power=new NicrosilLedger.Entry(UUID.randomUUID(),0,"a:steel",1.5,150);assertTrue(mind.add(power,32));assertEquals(power,ledger.get(mind.id).remove(power.id()));assertNull(ledger.get(mind.id).remove(power.id()));assertEquals(0,mind.used());assertTrue(ledger.erase(mind.id));assertNull(ledger.get(mind.id));}
    @Test void identityCapacityAndRecombiningRulesPreserveContents(){var owner=UUID.randomUUID();var mind=new NicrosilLedger.Mind(UUID.randomUUID(),owner,600);assertTrue(mind.accessible(owner,true));assertFalse(mind.accessible(UUID.randomUUID(),true));assertTrue(mind.add(new NicrosilLedger.Entry(UUID.randomUUID(),0,"f:gold",1.5,150),32));assertFalse(mind.add(new NicrosilLedger.Entry(UUID.randomUUID(),0,"f:steel",5,500),32));assertEquals(150,mind.used());assertTrue(NicrosilLedger.canReceive(0,1.5));assertTrue(NicrosilLedger.canReceive(1,1.5));assertFalse(NicrosilLedger.canReceive(1023,1.5));assertEquals(150,NicrosilLedger.powerCharge(1.5,100));assertEquals(0,NicrosilLedger.powerCharge(Double.NaN,100));}
    @Test void fractionsAccumulateAtAStableIdAndRespectCapacity(){var mind=new NicrosilLedger.Mind(UUID.randomUUID(),null,100);var first=new NicrosilLedger.Entry(UUID.randomUUID(),0,"a:steel",.25,25);assertTrue(mind.deposit(first,1));assertTrue(mind.deposit(new NicrosilLedger.Entry(UUID.randomUUID(),0,"a:steel",.25,25),1));assertEquals(1,mind.entries().size());assertEquals(.5,mind.entry(first.id()).amount());assertEquals(50,mind.used());assertFalse(mind.deposit(new NicrosilLedger.Entry(UUID.randomUUID(),0,"a:steel",1,100),1));assertEquals(.005,NicrosilProgress.step(.5,1,100,100,.1,1),1e-12);assertEquals(.5,NicrosilProgress.target(1,.5));}
    @Test void malformedOrUnboundedContentsAreRejected(){assertThrows(IllegalArgumentException.class,()->new NicrosilLedger.Entry(UUID.randomUUID(),0,"a:steel",Double.NaN,1));assertThrows(IllegalArgumentException.class,()->new NicrosilLedger.Mind(UUID.randomUUID(),null,-1));var mind=new NicrosilLedger.Mind(UUID.randomUUID(),null,10000);for(int i=0;i<256;i++)assertTrue(mind.add(new NicrosilLedger.Entry(UUID.randomUUID(),1,"future:resource",1,1),10000));assertFalse(mind.add(new NicrosilLedger.Entry(UUID.randomUUID(),1,"future:resource",1,1),10000));}
}
